def ic(k, uid="", sz=20, cls="ic", mode="vc"):
    d = ICONOS[k][mode]
    if uid:
        d = re.sub(r"id=\"([^\"]+)\"", f"id=\"ic_{k}_{uid}\"", d)
        d = re.sub(r"url\(#([^\)]+)\)", f"url(#ic_{k}_{uid})", d)
    d = re.sub(r"<svg [^>]*>", f"<svg class=\"{cls}\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\" width=\"{sz}\" height=\"{sz}\" aria-hidden=\"true\" style=\"color:currentColor\">", d, count=1)
    return d
